<style>
:root{--ec9-blue:#177be6;--ec9-blue-dark:#0861c7;--ec9-yellow:#ffd51f;--ec9-red:#d90624;--ec9-orange:#ff7200;--ec9-ink:#111827;--ec9-muted:#697386;--ec9-bg:#f1f4f8;--ec9-line:#e4e7ec;--ec9-radius:14px}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--ec9-bg);color:var(--ec9-ink);font-family:"Be Vietnam Pro",sans-serif;font-size:15px}.ec9-page a{color:inherit;text-decoration:none}.ec9-page img{display:block;max-width:100%}.ec9-page button,.ec9-page input{font:inherit}.ec9-container{width:min(1780px,calc(100% - 40px));margin-inline:auto}.ec9-header{position:relative;z-index:30;background:var(--ec9-blue);color:#fff}.ec9-header-main{height:108px;display:grid;grid-template-columns:330px minmax(280px,1fr) auto auto;gap:28px;align-items:center}.ec9-logo{display:flex;align-items:center;gap:12px;color:#fff}.ec9-logo img{width:auto;max-width:285px;height:62px;object-fit:contain}.ec9-logo-mark{display:grid;place-items:center;width:56px;height:56px;border-radius:16px;background:var(--ec9-yellow);color:var(--ec9-blue);font-size:28px;transform:skew(-8deg)}.ec9-logo b{display:block;font-size:30px;letter-spacing:-1.5px}.ec9-logo small{display:block;margin-top:2px;font-size:10px;letter-spacing:2px;text-transform:uppercase;opacity:.85}.ec9-search{height:56px;border-radius:12px;background:#fff;display:flex;overflow:hidden;box-shadow:0 4px 16px #0055ad26}.ec9-search input{min-width:0;flex:1;border:0;outline:0;padding:0 20px;color:#2b303b}.ec9-search button{width:64px;border:0;background:#fff;color:#111;font-size:22px;cursor:pointer}.ec9-head-links{display:flex;gap:26px}.ec9-head-links a{display:flex;align-items:center;gap:10px;white-space:nowrap}.ec9-head-links i{font-size:26px}.ec9-head-links small,.ec9-head-links b{display:block}.ec9-head-links small{font-size:13px}.ec9-head-links b{font-size:18px}.ec9-actions{display:flex;align-items:center;gap:18px}.ec9-actions a,.ec9-actions button{position:relative;border:0;background:transparent;color:#fff;font-size:24px;cursor:pointer;padding:4px}.ec9-actions em{position:absolute;right:-7px;top:-8px;display:grid;place-items:center;width:20px;height:20px;border-radius:50%;background:var(--ec9-yellow);color:#111;font-size:11px;font-style:normal;font-weight:800}.ec9-nav-wrap{background:var(--ec9-yellow);color:#111}.ec9-nav{height:58px;display:flex;align-items:center}.ec9-category-trigger{align-self:stretch;width:330px;display:flex;align-items:center;gap:12px;border:0;background:#f7c900;padding:0 20px;font-size:18px;font-weight:700;cursor:pointer}.ec9-category-trigger i:last-child{margin-left:auto}.ec9-nav nav{height:100%;flex:1;display:flex;justify-content:space-around;align-items:center}.ec9-nav nav a{font-weight:700;white-space:nowrap;padding:18px 15px;transition:.2s}.ec9-nav nav a:hover{color:var(--ec9-blue-dark)}.ec9-mobile-menu{display:none}.ec9-main{padding-bottom:64px}.ec9-hero-section{padding:16px 0 0}.ec9-hero-grid{display:grid;grid-template-columns:330px minmax(0,1fr);gap:16px}.ec9-category-rail{background:#fff;border-radius:0 0 var(--ec9-radius) var(--ec9-radius);overflow:hidden;box-shadow:0 8px 30px #2539540d}.ec9-category-rail a{min-height:64px;display:grid;grid-template-columns:42px 1fr auto;gap:12px;align-items:center;padding:8px 16px;border-bottom:1px solid #edf0f4;font-size:16px}.ec9-category-rail a:hover{background:#f3f8ff;color:var(--ec9-blue)}.ec9-category-rail img{width:38px;height:38px;object-fit:contain}.ec9-category-rail i{font-size:12px}.ec9-hero-slider{position:relative;min-height:580px;border-radius:0 0 var(--ec9-radius) var(--ec9-radius);overflow:hidden;background:var(--ec9-blue)}.ec9-hero-slide{position:absolute;inset:0;opacity:0;visibility:hidden;transition:opacity .55s ease}.ec9-hero-slide.is-active{opacity:1;visibility:visible}.ec9-hero-slide>img{width:100%;height:100%;object-fit:cover}.ec9-hero-copy{position:absolute;left:6%;top:50%;width:min(500px,45%);transform:translateY(-50%);color:#fff;text-shadow:0 2px 16px #003b8059}.ec9-hero-copy small{display:inline-block;background:var(--ec9-yellow);color:#111;border-radius:999px;padding:8px 14px;font-weight:800}.ec9-hero-copy h1{margin:18px 0 12px;font-size:clamp(34px,4vw,66px);line-height:1.05}.ec9-hero-copy p{max-width:460px;font-size:18px;line-height:1.6}.ec9-hero-copy a{display:inline-flex;align-items:center;gap:10px;margin-top:12px;padding:13px 22px;background:#fff;color:var(--ec9-blue-dark);border-radius:10px;font-weight:800}.ec9-slide-prev,.ec9-slide-next{position:absolute;z-index:3;top:50%;width:42px;height:42px;border:0;border-radius:50%;background:#ffffffd9;color:#111;cursor:pointer;transform:translateY(-50%)}.ec9-slide-prev{left:18px}.ec9-slide-next{right:18px}.ec9-dots{position:absolute;z-index:3;bottom:18px;left:50%;display:flex;gap:8px;transform:translateX(-50%)}.ec9-dots button{width:10px;height:10px;padding:0;border:0;border-radius:50%;background:#ffffff8a}.ec9-dots button.is-active{width:28px;border-radius:10px;background:#fff}.ec9-section{padding-top:34px}.ec9-section h2{margin:0 0 26px;font-size:30px;letter-spacing:-.5px}.ec9-panel{padding:28px;background:#fff;border-radius:var(--ec9-radius);box-shadow:0 10px 35px #25395408}.ec9-categories{display:grid;grid-template-columns:repeat(6,1fr);gap:20px 28px}.ec9-categories a{display:flex;align-items:center;gap:14px;min-width:0;font-size:17px;font-weight:600}.ec9-categories img{width:76px;height:76px;object-fit:contain;transition:.25s}.ec9-categories a:hover img{transform:translateY(-4px)}.ec9-sale-panel{padding:30px 22px 24px;background:linear-gradient(135deg,#ff7800,#f24c00);border-radius:var(--ec9-radius)}.ec9-sale-panel>h2{color:#fff;text-align:center;text-transform:uppercase}.ec9-product-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px}.ec9-product{min-width:0;overflow:hidden;background:#fff;border:1px solid var(--ec9-line);border-radius:12px;transition:.22s}.ec9-product:hover{transform:translateY(-4px);box-shadow:0 12px 28px #17243b19}.ec9-product-image{position:relative;display:block;aspect-ratio:1/.93;overflow:hidden;background:#fff}.ec9-product-image>img{width:100%;height:100%;padding:12px;object-fit:contain;transition:.25s}.ec9-product:hover .ec9-product-image>i