group span{display:block;margin-top:8px;line-height:1.35}.ec9-campaigns{display:grid;grid-template-columns:1fr 1fr;grid-template-rows:280px 280px;gap:16px}.ec9-campaigns a{position:relative;overflow:hidden;border-radius:12px;background:#e6f5ff}.ec9-campaigns a:first-child{grid-row:1/3}.ec9-campaigns img{width:100%;height:100%;object-fit:cover;transition:.3s}.ec9-campaigns a:hover img{transform:scale(1.02)}.ec9-campaigns span{position:absolute;left:18px;bottom:18px;max-width:80%;padding:9px 13px;border-radius:8px;background:#ffffffdf;font-weight:700}.ec9-tabs{display:grid;grid-template-columns:repeat(6,1fr);gap:10px;margin-bottom:20px}.ec9-tabs a{display:flex;align-items:center;gap:12px;padding:10px 14px;border-radius:10px;background:#f0f2f5;font-weight:600}.ec9-tabs img{width:50px;height:50px;object-fit:contain}.ec9-product-grid-large{grid-template-columns:repeat(5,minmax(0,1fr));row-gap:18px}.ec9-brand-banner{position:relative;display:block;min-height:320px;overflow:hidden;border-radius:14px;background:#b49d7d}.ec9-brand-banner img{width:100%;height:100%;min-height:320px;object-fit:cover}.ec9-brand-banner>span{position:absolute;left:7%;top:50%;width:32%;transform:translateY(-50%);color:#fff;text-shadow:0 2px 14px #0006}.ec9-brand-banner small,.ec9-brand-banner b{display:block}.ec9-brand-banner small{font-weight:700;letter-spacing:2px}.ec9-brand-banner b{margin-top:12px;font-size:38px;line-height:1.2}.ec9-advice{display:grid;grid-template-columns:1fr 1fr;gap:22px}.ec9-advice-feature img{width:100%;aspect-ratio:1.65;object-fit:cover;border-radius:12px}.ec9-advice h3{margin:12px 0 8px;font-size:21px}.ec9-advice p{margin:0 0 10px;color:#626b78;line-height:1.6}.ec9-advice time{color:#8d949f}.ec9-advice-list article{display:grid;grid-template-columns:42% 1fr;gap:16px;padding:0 0 14px;margin-bottom:14px;border-bottom:1px solid var(--ec9-line)}.ec9-advice-list img{width:100%;aspect-ratio:1.8;object-fit:cover;border-radius:10px}.ec9-advice-list h3{margin:0 0 6px;font-size:17px}.ec9-advice-list p{font-size:14px;line-height:1.45}.ec9-footer{padding:55px 0;background:#070707;color:#fff}.ec9-footer-grid{display:grid;grid-template-columns:1.3fr 1fr 1fr 1.15fr;gap:42px 70px}.ec9-footer h3{margin:0 0 18px;font-size:20px}.ec9-footer p{margin:0 0 12px;color:#d4d7dc;line-height:1.65}.ec9-footer section>a,.ec9-footer section>span{display:flex;gap:10px;align-items:flex-start;margin:0 0 12px;color:#e4e5e8;line-height:1.5}.ec9-footer section>b{display:block;margin:-5px 0 18px;color:#ff8a00;font-size:20px}.ec9-footer section>b small{color:#ddd;font-size:13px}.ec9-social{display:flex;gap:10px}.ec9-social a{display:grid;place-items:center;width:46px;height:46px;border-radius:12px;background:var(--ec9-blue);font-size:22px}.ec9-social a:nth-child(2){background:#ee3a68}.ec9-social a:nth-child(3){background:#202020}.ec9-social a:nth-child(4){background:#e62117}.ec9-pay>div{display:flex;flex-wrap:wrap;gap:7px}.ec9-pay span{padding:10px 12px;border-radius:6px;background:#fff;color:#124078;font-weight:800;font-size:12px}.ec9-qr{display:flex;align-items:center;gap:14px}.ec9-qr>div{display:grid;place-items:center;width:88px;height:88px;background:#fff;color:#111;font-size:60px}.ec9-qr p{margin:0}.ec9-qr b{font-size:18px}.ec9-inner-hero{padding:52px 0;background:linear-gradient(135deg,var(--ec9-blue-dark),#1b94f1);color:#fff}.ec9-inner-hero h1{margin:8px 0 0;font-size:42px}.ec9-inner-hero p{margin:0;text-transform:uppercase;letter-spacing:2px}.ec9-content{padding:40px 0 70px}.ec9-prose{padding:28px;background:#fff;border-radius:14px;line-height:1.75}.ec9-prose>img{width:100%;max-height:520px;margin-bottom:24px;border-radius:12px;object-fit:cover}.ec9-listing{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.ec9-listing article{padding:14px;background:#fff;border-radius:12px}.ec9-listing img{width:100%;aspect-ratio:1.65;object-fit:cover;border-radius:9px}.ec9-listing h3{font-size:18px}.ec9-empty{padding:40px;background:#fff;border-radius:12px;text-align:center}
.ec9-button{display:inline-flex;justify-content:center;align-items:center;min-height:46px;padding:0 22px;border:0;border-radius:9px;background:var(--ec9-blue);color:#fff!important;font-weight:700;cursor:pointer}.ec9-form{display:grid;grid-template-columns:1fr 1fr;gap:14px;padding:26px;background:#fff;border-radius:14px}.ec9-form input,.ec9-form textarea,.ec9-form select{width:100%;min-height:50px;padding:12px 14px;border:1px solid #d8dee8;border-radius:8px;background:#fff;outline:0}.ec9-form textarea{grid-column:1/3;min-height:130px;resize:vertical}.ec9-form .ec9-button{width:max-content}
@media(max-width:1280px){.ec9-header-main{grid-template-columns:250px minmax(260px,1fr) auto auto;gap:18px}.ec9-head-links a:nth-child(2){display:none}.ec9-logo b{font-size:25px}.ec9-hero-grid{grid-template-columns:280px minmax(0,1fr)}.ec9-category-trigger{width:280px}.ec9-categories{grid-template-columns:repeat(4,1fr)}.ec9-needs{grid-template-columns:1.25fr repeat(2,1fr)}.ec9-need-group:last-child{display:none}.ec9-footer-grid{gap:36px}.ec9-nav nav a{padding-inline:9px;font-size:14px}}
@media(max-width:980px){.ec9-container{width:min(100% - 28px,1780px)}.ec9-header-main{height:auto;grid-template-columns:1fr auto;padding-block:15px;gap:14px}.ec9-logo{grid-column:1}.ec9-search{grid-column:1/3;grid-row:2}.ec9-head-links{display:none}.ec9-actions{grid-column:2;grid-row:1}.ec9-category-trigger{width:auto;flex:1}.ec9-mobile-menu{display:flex;align-items:center;gap:8px;height:100%;padding:0 18px;border:0;background:transparent;font-weight:700}.ec9-nav{position:relative}.ec9-nav nav{position:absolute;left:0;right:0;top:100%;height:auto;display:none;padding:12px;background:#fff;box-shadow:0 15px 30px #17243b24}.ec9-nav nav.is-open{display:grid}.ec9-nav nav a{padding:12px;border-bottom:1px solid #eee}.ec9-hero-grid{display:block}.ec9-category-rail{position:absolute;z-index:12;left:14px;right:14px;display:none}.ec9-category-rail.is-open{display:block}.ec9-hero-slider{min-height:490px;border-radius:var(--ec9-radius)}.ec9-categories{grid-template-columns:repeat(3,1fr)}.ec9-product-grid,.ec9-product-grid-large{grid-template-columns:repeat(3,1fr)}.ec9-needs{grid-template-columns:1fr 1fr}.ec9-need-lead{min-height:480px}.ec9-need-group:nth-child(4){display:block}.ec9-campaigns{grid-template-rows:220px 220px}.ec9-tabs{grid-template-columns:repeat(3,1fr)}.ec9-footer-grid{grid-template-columns:1fr 1fr}.ec9-brand-banner>span{width:42%}}
@media(max-width:640px){body{font-size:14px}.ec9-container{width:min(100% - 20px,1780px)}.ec9-logo-mark{width:44px;height:44px}.ec9-logo b{font-size:20px}.ec9-logo small{font-size:8px}.ec9-actions{gap:10px}.ec9-actions a,.ec9-actions button{font-size:20px}.ec9-search{height:48px}.ec9-category-trigger{font-size:15px}.ec9-hero-slider{min-height:420px}.ec9-hero-slide>img{object-position:65% center}.ec9-hero-copy{left:24px;top:auto;bottom:42px;width:80%;transform:none}.ec9-hero-copy h1{font-size:31px}.ec9-hero-copy p{font-size:14px}.ec9-slide-prev,.ec9-slide-next{display:none}.ec9-section{padding-top:22px}.ec9-section h2{margin-bottom:18px;font-size:23px}.ec9-panel{padding:18px 14px}.ec9-categories{grid-template-columns:repeat(2,1fr);gap:16px 8px}.ec9-categories img{width:54px;height:54px}.ec9-product-grid,.ec9-product-grid-large{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.ec9-product h3{font-size:14px}.ec9-price strong{font-size:15px}.ec9-needs{display:block}.ec9-need-lead{display:block;min-height:auto;aspect-ratio:1.2;margin-bottom:12px}.ec9-need-group{margin-bottom:12px}.ec9-need-group:nth-child(4){display:none}.ec9-campaigns{display:grid;grid-template-columns:1fr;grid-template-rows:260px 190px 190px}.ec9-campaigns a:first-child{grid-row:auto}.ec9-tabs{display:flex;overflow:auto}.ec9-tabs a{min-width:180px}.ec9-brand-banner{min-height:240px}.ec9-brand-banner img{min-height:240px;object-position:65% center}.ec9-brand-banner>span{left:24px;width:55%}.ec9-brand-banner b{font-size:24px}.ec9-advice{display:block}.ec9-advice-list{margin-top:22px}.ec9-advice-list article{grid-template-columns:38% 1fr}.ec9-advice-list p{display:none}.ec9-footer-grid{grid-template-columns:1fr;gap:28px}.ec9-listing{grid-template-columns:1fr}.ec9-inner-hero h1{font-size:32px}.ec9-form{grid-template-columns:1fr}.ec9-form textarea{grid-column:auto}}
